!function(){"use strict";const e={gd22:["2022 年广东卷","https://gaokao.eol.cn/shiti/zhenti/202206/W020220616377740816453.pdf"],zj23:["2023 年 6 月浙江卷","https://cdn.zizzs.com/zixunzhan/202310/2ab57aa6-3b25-4823-bae4-7497fa85cd51.pdf"],n23:["2023 年全国新课标卷","https://static-gkcx.gaokao.cn/upload/zhenti/20230613/1686651407_4038.pdf","看试题（整理版第 4 题）"],n24:["2024 年全国甲卷","https://down.jiaoyuwu.com/m00/37/06/d93c156d1a95ede711e34ee049fa10ca.pdf","看试题（整理版第 9 题）"],bj24:["2024 年北京卷","https://cdn.zgkao.com/17195390325742024%E5%8C%97%E4%BA%AC%E9%AB%98%E8%80%83%E7%9C%9F%E9%A2%98%E5%8C%96%E5%AD%A6%EF%BC%88%E6%95%99%E5%B8%88%E7%89%88%EF%BC%89.pdf"],ah24:["2024 年安徽卷","https://down.jiaoyuwu.com/m00/43/fe/2cba6a02ead6e16bc54bbba9c10583f1.pdf"],sd25:["2025 年山东卷","https://static-gkcx.gaokao.cn/upload/zhenti/20250613/1749812160_2083.pdf","查看试题整理版"],n25:["2025 年全国新课标理综卷","https://img.gaokaozhitongche.com/resource/pdf/paper/202507/20250728030001_5IZPSD.pdf#page=11"],n21:["2021 年全国乙卷","https://gaokao.neea.edu.cn/xhtml1/report/21121/3939-1.htm","查看官方评析"]},l=(l,o,m="")=>{const[t,O,a="查看试卷"]=e[l];return{id:l+"-"+o+m,label:t+"第 "+o+" 题"+m,url:O,link:a}},o=(e,l,o,m)=>({prompt:e,options:l,correct:o,feedback:m}),m=(e,...l)=>({...o(...l),source:e});window.ChemStudyExams={titration:{example:{title:"食醋中的醋酸浓度",source:l("gd22",17,"（4）ⅰ 浓度小问"),stem:"取 20.00 mL 醋酸溶液，用 0.1000 mol/L 的 NaOH 滴定，达到终点时用掉 22.08 mL。求这份醋酸溶液的物质的量浓度。",hints:["先圈出「用掉」和标准液浓度。","一分子醋酸只有一个可被 NaOH 中和的羧基氢。","用碱的用量求酸的物质的量，再除以取样体积。"],worked:"终点附近按 1∶1 中和。c(醋酸)＝c(NaOH) × V(NaOH) ÷ V(醋酸)＝0.1000 × 22.08 ÷ 20.00＝0.1104 mol/L。两边体积同用 mL，比例里单位抵消。"},moves:[o("标准液消耗体积用哪个？",["20.00 mL","22.08 mL","22.08−20.00 mL"],1,["20.00 mL 是移取的酸。","题目已经给出标准液的用量。","题目给的是两种液体的体积，不能相减。"]),o("醋酸与 NaOH 中和的物质的量之比是多少？",["1∶2","2∶1","1∶1"],2,["一个羧基消耗一个 OH⁻。","按 CH₃COOH ＋ OH⁻ → CH₃COO⁻ ＋ H₂O 的计量关系判断。","弱酸也按中和反应的计量关系计算。"]),o("醋酸浓度怎么列式？",["0.1000 × 22.08 ÷ 20.00","0.1000 × 20.00 ÷ 22.08","0.1000 × 22.08 ÷ 1000"],0,["碱的用量乘浓度，再除以酸的取样体积。","分母应为醋酸样品的体积。","该式得到 NaOH 的物质的量，单位是 mol。"])],practice:m(l("n24",27,"（6）"),"用高锰酸钾滴定测过氧化脲纯度。下面哪种操作会让算出的纯度偏低？",["配制样品时，容量瓶液面超过刻度","滴定管用水洗过，未用标准液润洗","滴定管尖嘴里的气泡在滴定中消失"],0,["样品被稀释，取等体积时含待测物偏少，标准液用量偏小。","标准液被残水稀释，实际要用更大体积。仍用标称浓度算会偏高。","读数差含填入尖嘴的液体，导致计算结果偏高。"]),recall:m(l("n24",27,"（5）D 项"),"酸性高锰酸钾滴定时，锥形瓶内第一次出现微红色。该在什么时候记末读数？",["只要刚变色就记","摇匀后微红色约半分钟不消失再记","等溶液变成深紫色再记"],1,["瞬时变色可能是试剂尚未混匀。","确认有少量高锰酸根保持在溶液中，再记录终点读数。","深紫色通常说明已明显过量。"])},ions:{example:{title:"足量 CO₂ 通入次氯酸钙溶液",source:l("zj23",9," B 项"),stem:"在次氯酸钙溶液里通入足量 CO₂。把反应写成净离子方程式，并检查钙离子是否应写进去。",hints:["「足量」决定碳最终以哪种含碳微粒存在。","用碳酸的一级电离和次氯酸根结合 H⁺ 来看。","钙离子在这组条件下仍在溶液中。"],worked:"CO₂ 足量时，最终含碳产物按 HCO₃⁻ 处理。ClO⁻ 接受 H⁺ 生成 HClO，Ca²⁺ 是旁观离子。净离子方程式为 ClO⁻ ＋ CO₂ ＋ H₂O → HClO ＋ HCO₃⁻，两侧总电荷均为 −1。"},moves:[o("足量 CO₂ 条件下，最后的含碳微粒选哪个？",["CO₃²⁻","HCO₃⁻","C₂O₄²⁻"],1,["继续通入 CO₂ 后，应考虑碳酸根向碳酸氢根转化。","足量 CO₂ 下这里按碳酸氢根处理。","题干没有形成草酸根的反应。"]),o("ClO⁻ 反应后主要写成什么？",["Cl₂","Cl⁻","HClO"],2,["题中关注酸碱反应，氯价态保持 +1。","变成氯离子需要还原。","ClO⁻ 接受一个 H⁺ 变成次氯酸。"]),o("净离子方程式里怎样处理 Ca²⁺？",["在两边消去","把它写成金属钙","必须作为反应物且无对应产物"],0,["终态按可溶的碳酸氢钙体系判断，Ca²⁺ 不参与这条净反应。","没有金属钙析出。","净方程不能让钙原子凭空消失。"])],practice:m(l("sd25",5," C 项"),"MnO₂ 和浓盐酸加热制 Cl₂。净离子式除了 1 个 MnO₂，还应写入多少个 H⁺ 和 Cl⁻？",["2 个 H⁺ 和 2 个 Cl⁻","4 个 H⁺ 和 2 个 Cl⁻","4 个 H⁺ 和 4 个 Cl⁻"],1,["两个氧进入 2H₂O，要用 4H⁺。","MnO₂ ＋ 4H⁺ ＋ 2Cl⁻ → Mn²⁺ ＋ Cl₂↑ ＋ 2H₂O，两侧总电荷都为 +2。","只有两个 Cl⁻ 被氧化。其余氯离子不写入净反应。"]),recall:m(l("bj24",5," D 项"),"用 Na₂CO₃ 溶液把水垢中的固体 CaSO₄ 转成 CaCO₃。净离子方程式的产物端还应写什么？",["Na⁺","Ca²⁺","SO₄²⁻"],2,["Na⁺ 在转化中是旁观离子。","钙已经写在 CaCO₃ 里。","CaSO₄(s)＋CO₃²⁻ → CaCO₃(s)＋SO₄²⁻。硫酸根从原固相进入溶液。"])},redox:{example:{title:"高锰酸钾和碘化钾的计量关系",source:l("bj24",14," B 项"),stem:"同样取 0.001 mol KI，酸性时消耗 n mol KMnO₄，生成 Mn²⁺ 和 I₂；中性时消耗 10n mol KMnO₄，产物为 MnO₂ 和 IOₓ⁻。根据两组电子守恒求 x。",hints:["酸性组先看 Mn 从 +7 变到多少。","酸性组中每个 I⁻ 到 I₂ 只失去一个电子。","用中性组得电子量除以碘离子的量，再由 IOₓ⁻ 的电荷求 x。"],worked:"酸性组 5n＝0.001，得 n＝0.0002。中性组每个 Mn 得 3e⁻，共得 3×10n＝0.006 mol 电子。每个 I⁻ 失 6e⁻，碘由 −1 变 +5。5−2x＝−1，所以 x＝3。"},moves:[o("酸性组每个 Mn 从 +7 变为 +2，转移几个电子？",["失 5 个","得 3 个","得 5 个"],2,["化合价降低对应得电子。","3 对应 +7 到 +4。","+7 降到 +2，得 5 个。"]),o("酸性组 n(KMnO₄) 是多少？",["0.0002 mol","0.001 mol","0.005 mol"],0,["0.001 mol I⁻ 共失 0.001 mol 电子，因此 5n＝0.001。","每个 Mn 得 5 个电子，不能按 1∶1。","应除以 5。"]),o("中性组按 3×10n 算得电子数，IOₓ⁻ 中的 x 是？",["2","3","4"],1,["中性组总共得 0.006 mol 电子，每个 I⁻ 失 6 个。","碘变为 +5，满足 5−2×3＝−1。","x＝4 要求碘为 +7，不符合电子守恒。"])],practice:m(l("ah24",6," C 项"),"3.3 g 羟胺 NH₂OH 完全变为 NO₂⁻。已知羟胺摩尔质量 33 g/mol，这一转化转移多少电子？",["0.4 mol","0.2 mol","0.6 mol"],0,["N 从 −1 升至 +3，每个 N 失 4e⁻。0.10×4＝0.40 mol。","需由分子和离子的总电荷分别求 N 的价态。","亚硝酸根中 N 为 +3。+5 对应硝酸根。"]),recall:m(l("gd22",18,"（6）①"),"还原熔融的 YCl₃ 和 PtCl₄ 来制 Pt₃Y。按原料里的金属离子还原成零价组分计算，生成 1 mol 合金式量对应多少 mol 电子？",["7 mol","12 mol","15 mol"],2,["Pt₃Y 中有三个 Pt，Pt 的电子数要乘三。","12 mol 只计了铂，还要加上钇。","3 个 Pt(Ⅳ) 各得 4e⁻，1 个 Y(Ⅲ) 得 3e⁻，共 15 mol。"])},dilution:{example:{title:"配制过氧化脲溶液",source:l("n24",27,"（4）"),stem:"为了测纯度，把称取的过氧化脲溶于水并配成 100 mL 溶液。原题把洗涤烧杯和玻璃棒的操作安排了三次。想一想洗液该倒去哪、为什么要洗、定容后还要做什么。",hints:["配液要保证称取的溶质都转入容量瓶。","玻璃器皿上可能附着少量溶液。","贴近刻度后用滴管定容，最后浓度应处处相同。"],worked:"用少量蒸馏水反复洗涤烧杯和玻璃棒，将洗液全部转入 100 mL 容量瓶，尽量减少溶质损失。定容到刻度线后，塞紧瓶塞并反复倒转摇匀。"},moves:[o("三次洗液应该倒到哪里？",["废液缸","同一个容量瓶","另一个量筒后弃去"],1,["洗液里含有称取的部分溶质。","洗液与原溶液一起定容。","丢弃洗液会少算溶质。"]),o("反复洗涤主要避免哪种误差？",["水使溶质挥发","容量瓶刻度变动","溶质残留在烧杯或玻璃棒上"],2,["本步骤主要针对转移损失。","容量瓶刻度不因清洗改变。","把溶质尽量全部转移，维持预期物质的量。"]),o("液面达到刻度以后还需什么操作？",["盖好瓶塞，倒转摇匀","补水使液面超过刻度","静置分层后取上层"],0,["定容解决总体积，摇匀保证溶液浓度均一。","超过刻度会引入体积误差。","需要混匀，无须分层。"])],practice:m(l("sd25",4),"用 1.6 g NaOH 配出约 400 mL、约 0.10 mol/L 的溶液。哪件器材无需用到？",["100 mL 烧杯","500 mL 容量瓶","500 mL 量筒"],1,["可先在小烧杯中溶解 NaOH 并冷却。","这里要求近似配制 400 mL。500 mL 容量瓶只有 500 mL 的刻度，不能拿来定容 400 mL。","用 500 mL 量筒可近似量取所需体积。"]),recall:m(l("gd22",17,"（1）"),"用 5 mol/L 的醋酸溶液配出 250 mL、0.1 mol/L 的醋酸溶液。需要取多少浓溶液？",["5.0 mL","50 mL","12.5 mL"],0,["稀释前后醋酸的物质的量相等，V₁＝0.1×250÷5＝5.0 mL。","两种浓度的倍数是 50，体积取 250 mL 的五十分之一。","算完目标物质的量后，还要除以原溶液的浓度。"])},cell:{example:{title:"锌–五氧化二钒电池",source:l("n23",10),stem:"一节可充电的水系电池以 Zn 和 V₂O₅ 为电极。放电时 Zn²⁺ 嵌入 V₂O₅ 层间生成 ZnₓV₂O₅·nH₂O。根据反应方向判电极，判断充电总反应是不是放电的逆过程。",hints:["判断放电时金属 Zn 到 Zn²⁺ 的电子变化。","原电池正极发生还原。","把充电和放电的总反应分别写出来，再比方向。"],worked:"放电负极为 Zn，发生 Zn → Zn²⁺＋2e⁻；正极为 V₂O₅ 一侧，接受电子并嵌入 Zn²⁺。放电总反应是 xZn＋V₂O₅＋nH₂O → ZnₓV₂O₅·nH₂O，充电为其逆过程。原题 C 把放电反应写成充电。"},moves:[o("放电时，哪一极发生氧化？",["Zn 电极","V₂O₅ 电极","两极都氧化"],0,["Zn 失电子生成 Zn²⁺。","V₂O₅ 一侧接受电子。","放电时氧化与还原分别发生。"]),o("放电时 Zn²⁺ 朝哪边迁移？",["朝锌电极","只在外导线里移动","朝 V₂O₅ 一侧"],2,["Zn²⁺ 从锌一侧生成，并在 V₂O₅ 一侧被嵌入。","电解液中迁移的是离子，外导线里移动的是电子。","题干给出了嵌入 V₂O₅ 的过程。"]),o("充电总反应应怎样写？",["沿用放电方向","把放电反应反向写","只把产物中的水移到左边"],1,["沿用方向就是继续放电。","整体把放电的反应物和产物调换。","反向的是整个总反应。"])],practice:m(l("ah24",11," D 项"),"一节水系锌电池放电，0.65 g 锌变为 Zn²⁺。用题设 M(Zn)＝65 g/mol，求转移电子的量。",["0.010 mol","0.020 mol","0.040 mol"],1,["0.010 mol 是锌的量，每个 Zn 会失两个电子。","0.65÷65×2＝0.020 mol。","总反应两极转移的电子是同一批，不能重复计数。"]),recall:m(l("gd22",18,"（6）②"),"碱性氢氧燃料电池用 Pt₃Y/C 催化氧气还原。正极反应是哪条？",["O₂＋4H⁺＋4e⁻ → 2H₂O","O₂＋2H₂O＋4e⁻ → 4OH⁻","4OH⁻ → O₂＋2H₂O＋4e⁻"],1,["这是在酸性条件下常写的形式。","碱性介质中氧气得电子生成 OH⁻，原子和电荷都守恒。","这是氧化方向，氧气应当被消耗。"])},equilibrium:{example:{title:"氧化氯化氢时升温对平衡的影响",source:l("bj24",10," C 项"),stem:"催化回收 HCl 可用反应 4HCl(g)＋O₂(g) ⇌ 2Cl₂(g)＋2H₂O(g)，ΔH＝−114.4 kJ/mol。在此反应中，温度升高会怎样改变平衡常数？",hints:["先把 ΔH 的符号翻译成正反应的热效应。","升温相当于加入热量，平衡倾向吸热方向。","K 代表平衡时产物项与反应物项的比值。"],worked:"ΔH＜0，正反应放热。升温有利于吸热的逆反应，平衡相对偏向反应物。因此这个反应按给定方向写时，升温使 K 减小。催化剂改变速率，不改变同温下的平衡常数。"},moves:[o("ΔH 为负表示什么？",["正反应吸热","正反应放热","正反应没有热效应"],1,["ΔH 大于零才是正反应吸热。","生成物总焓低于反应物。","题干给出的 ΔH 不等于零。"]),o("升温时，平衡偏向哪一边？",["偏向反应物","偏向产物","一定不动"],0,["逆向是吸热方向。","正向放热，升温相对不利。","改温度会改变这个反应的平衡组成。"]),o("按题干方向写的平衡常数如何变化？",["增大","不变","减小"],2,["升温后相对不利于正向生成产物。","温度是决定该反应 K 值的条件。","温度升高，放热反应的 K 减小。"])],practice:m(l("sd25",10," B 项"),"恒温恒容，Na₂SiF₆(s) ⇌ 2NaF(s)＋SiF₄(g) 已平衡。向容器加 N₂，N₂ 不参与反应。SiF₄ 的分压怎样变？",["减小","增大","不变"],2,["分压 pᵢ＝nᵢRT/V。不能只看气相摩尔分数变小。","增加的是总压，SiF₄ 的 n、T、V 没有随加氮直接改变。","在恒温恒容下，SiF₄ 的分压和该反应的反应商保持原值，平衡不移动。"]),recall:m(l("bj24",12," A 项"),"同一温度下，用给定方程式计算得到反应商 Q 小于平衡常数 K。反应接下来净向哪边进行？",["逆反应方向","已处于平衡","正反应方向"],2,["逆向消耗产物会使 Q 更小，离 K 更远。","Q＝K 才表示当前组成满足平衡。","正向生成产物使 Q 增大，直到达到 K。"])},polarity:{example:{title:"氨与氘代氨的分子极性",source:l("bj24",9," B 项"),stem:"把 NH₃ 的三个 H 换成 D（氢的同位素）得到 ND₃。用中心氮的电子域和分子构型判断，两种分子是否都是极性分子？",hints:["D 与 H 的核外电子数相同。","数 N 周围的三个成键方向，再加一对孤电子。","三根键的偶极在三角锥轴线上是否完全抵消？"],worked:"H 与 D 同属氢元素。两种分子的中心 N 都有 3 个成键电子域和 1 对孤电子，原子形成三角锥。键偶极的合量不为零，所以 NH₃ 和 ND₃ 都是极性分子。"},moves:[o("换用 D 会怎样改变中心 N 的电子域数？",["减少为 3","增加为 5","保持为 4"],2,["还需把 N 的孤电子对计入。","同位素替换不增加一个新的成键方向。","两种分子都是 3 个成键域和 1 个孤电子域。"]),o("只看原子位置，两种分子是什么构型？",["三角锥形","平面三角形","直线形"],0,["中心 N 位于三个外围原子组成的平面之外。","四个电子域中有一个为孤电子对。","中心周围有三个成键方向。"]),o("两种分子的极性如何判断？",["只有 NH₃ 有极性","两种都有极性","两种都无极性"],1,["D 的替换不让 ND₃ 变成可完全抵消键偶极的构型。","三角锥中三根键的偶极合量不为零。","要看键偶极在三维空间中的合量。"])],practice:m(l("n21",35,"（3）键角小问"),"比较 H₂O 和 NH₃。用价层电子对互斥解释，为什么 H₂O 的键角较小？",["水有两对孤电子，对成键电子域的挤压更明显","水没有孤电子对","NH₃ 的氢原子都和氮在同一直线上"],0,["H₂O 有 2 对孤电子，NH₃ 有 1 对。孤电子域的排斥较强，水的成键角被压得更小。","水中 O 有 2 对孤电子。","氨呈三角锥形。"]),recall:m(l("sd25",7," B 项"),"叠氮离子 N₃⁻ 的三个 N 连成一串。判断这三个 N 的空间构型。",["直线形","V 形","三角锥形"],0,["中心 N 两侧各有一个成键电子域，中心无孤电子对，构型为直线。","V 形需要中心周围有能改变构型的额外孤电子域。","三角锥需要三个外围原子。"])},ester:{example:{title:"用燃烧热求乙酸乙酯生成反应的焓变",source:l("n25",28,"（1）"),stem:"液态乙酸、乙醇、乙酸乙酯的燃烧焓依次是 −874、−1367、−2238 kJ/mol。求液态乙酸与乙醇按 1∶1 生成液态乙酸乙酯和水的反应焓变。",hints:["比较反应前后的 C、H、O 原子数。","把反应物分别完全燃烧，结果与生成酯后再燃烧相同。","先把两个反应物的燃烧焓相加，再减去酯的燃烧焓。"],worked:"酯化为乙酸＋乙醇 → 乙酸乙酯＋水。把反应物分别完全燃烧，或先酯化再燃烧酯，终态相同。由盖斯定律，ΔH＝(−874−1367)−(−2238)＝−3 kJ/mol。"},moves:[o("酯化时，除乙酸乙酯外还生成什么？",["氧气","水","二氧化碳"],1,["酯化不会放出 O₂。","乙酸和乙醇缩合，同时生成水。","二氧化碳是完全燃烧的产物。"]),o("哪两条路径到同一燃烧终态？",["只燃烧乙酸，或只燃烧乙醇","只燃烧乙醇，或只燃烧酯","分别燃烧两种反应物，或先酯化再燃烧酯"],2,["两种单独燃烧的物质元素组成不同。","乙醇与酯的碳原子数不同。","两边总原子数相同，燃烧终态相同。"]),o("酯化焓变为多少？",["−3 kJ/mol","+3 kJ/mol","−4479 kJ/mol"],0,["用反应物燃烧焓之和减去酯的燃烧焓。","相减方向颠倒了。","酯的燃烧焓需要被减去，不能直接相加。"])],practice:m(l("ah24",9," B 项"),"实验制乙酸乙酯时，用饱和 Na₂CO₃ 溶液接收馏出物。它对馏出物中的少量乙酸有什么作用？",["氧化乙酸","中和乙酸","让乙酸继续与乙醇酯化"],1,["这里主要发生酸碱反应。","Na₂CO₃ 中和乙酸，生成乙酸盐等，便于酯与水相分离。","接收液是碱性的，功能是处理馏出物。"]),recall:m(l("n25",28,"（4）提高产率小问"),"乙酸和乙醇可逆生成乙酸乙酯和水。哪种做法能通过平衡移动提高酯的产率？",["反应中设法移去部分生成水","只多加催化剂","反应中不断加入水"],0,["降低产物水的量，有利于平衡向生成酯的一侧移动。","催化剂主要改变到达平衡的速率。","增加水会使平衡相对偏向水解一侧。"])}}}();
